from datetime import datetime
from typing import Optional
from sqlalchemy import CheckConstraint, DateTime, ForeignKey, Integer, Numeric, String, Text
from sqlalchemy.orm import Mapped, mapped_column
from backend.app.database.base import Base, TimestampMixin


class TradingSignal(Base, TimestampMixin):
    """Trading signal generated by strategy scanners."""
    __tablename__ = "trading_signals"
    __table_args__ = (CheckConstraint("trigger_price > 0 AND stop_loss > 0 AND target_price > 0", name="ck_signal_prices_positive"),)

    id: Mapped[int] = mapped_column(Integer, primary_key=True, autoincrement=True)
    session_id: Mapped[Optional[int]] = mapped_column(
        Integer,
        ForeignKey("trading_sessions.id", ondelete="SET NULL"),
        nullable=True,
        index=True,
    )
    instrument_id: Mapped[int] = mapped_column(
        Integer,
        ForeignKey("instruments.id", ondelete="CASCADE"),
        nullable=False,
        index=True,
    )
    strategy_name: Mapped[str] = mapped_column(String(64), nullable=False, index=True)
    signal_type: Mapped[str] = mapped_column(String(16), nullable=False)  # BUY, SELL
    trigger_price: Mapped[float] = mapped_column(Numeric(18, 4), nullable=False)
    stop_loss: Mapped[float] = mapped_column(Numeric(18, 4), nullable=False)
    target_price: Mapped[float] = mapped_column(Numeric(18, 4), nullable=False)
    status: Mapped[str] = mapped_column(
        String(32),
        default="GENERATED",
        nullable=False,
        index=True,
    )  # GENERATED, RISK_APPROVED, RISK_REJECTED, EXECUTED, EXPIRED
    rejection_reason: Mapped[Optional[str]] = mapped_column(Text, nullable=True)
    generated_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)
